static long Sum(long[] a, int lo, int hi) {
    if (hi - lo < 10_000) return a[lo..hi].Sum();        // leaf
    int mid = (lo + hi) / 2;
    long l = 0, r = 0;
    Parallel.Invoke(                                     // fork
        () => l = Sum(a, lo, mid),
        () => r = Sum(a, mid, hi));                      // join on return
    return l + r;
}
